CREATE FUNCTION public.payroll_approve_work_draft(t uuid,y integer,m integer,rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE preview jsonb;r jsonb;a jsonb;gross numeric;ee numeric;er numeric;rev integer;BEGIN
IF NOT public.people_owner(t,auth.uid()) OR NOT public.payroll_manager(t,auth.uid()) THEN RAISE EXCEPTION 'Owner approval required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));IF EXISTS(SELECT 1 FROM public.hr_payroll WHERE tenant_id=t AND year=y AND month=m) OR EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status='approved') THEN RAISE EXCEPTION 'Saved payroll is read-only';END IF;
preview:=public.payroll_work_preview(t,y,m);IF jsonb_array_length(preview)=0 OR jsonb_array_length(preview)<>jsonb_array_length(rows) THEN RAISE EXCEPTION 'Whole month draft required';END IF;
FOR r IN SELECT value FROM jsonb_array_elements(preview) LOOP IF jsonb_array_length(r->'preparation'->'missing')>0 THEN RAISE EXCEPTION 'Missing verified inputs for %',r->>'name';END IF;IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rows) x WHERE x->>'employee_id'=r->>'employee_id') THEN RAISE EXCEPTION 'Missing person';END IF;END LOOP;
PERFORM public.payroll_save_work_draft(t,y,m,rows);
FOR r IN SELECT value FROM jsonb_array_elements(preview) LOOP
SELECT x->'amounts' INTO a FROM jsonb_array_elements(rows) x WHERE x->>'employee_id'=r->>'employee_id';gross:=round((a->>'basic')::numeric+(a->>'al')::numeric+(a->>'sh')::numeric+(a->>'sick')::numeric+(a->>'unpaid')::numeric+(a->>'overtime')::numeric+(a->>'other')::numeric,2);IF gross<0 THEN RAISE EXCEPTION 'Gross pay cannot be negative';END IF;ee:=CASE WHEN gross<7100 THEN 0 ELSE least(1500,round(gross*.05,2)) END;er:=least(1500,round(gross*.05,2));
INSERT INTO public.hr_payroll(tenant_id,employee_id,year,month,forecast_base_salary,actual_base_salary,earned_salary_override,annual_leave_pay,statutory_holiday_pay,actual_overtime,adjustments_override,other_payments_note,unpaid_leave_deduction,gross_salary,mpf_employee,mpf_employer,net_salary,mpf_payment_amount,total_deductions,payment_status,preparation)
VALUES(t,(r->>'employee_id')::uuid,y,m,(a->>'basic')::numeric,(a->>'basic')::numeric,(a->>'basic')::numeric,(a->>'al')::numeric,(a->>'sh')::numeric,(a->>'overtime')::numeric,(a->>'other')::numeric,COALESCE((SELECT x->'notes'->>'other' FROM jsonb_array_elements(rows) x WHERE x->>'employee_id'=r->>'employee_id'),''),-(a->>'unpaid')::numeric,gross,ee,er,gross-ee,ee+er,ee,'draft',r->'preparation'||jsonb_build_object('sickness_allowance',(a->>'sick')::numeric,'source','confirmed_work_draft','amounts',a,'source_fingerprint',r->>'source_fingerprint'));
END LOOP;
INSERT INTO public.hr_payroll_months(tenant_id,year,month,prepared_by,prepared_at,revision) VALUES(t,y,m,auth.uid(),now(),1) ON CONFLICT(tenant_id,year,month) DO UPDATE SET prepared_by=auth.uid(),prepared_at=now(),revision=hr_payroll_months.revision+1 RETURNING revision INTO rev;
RETURN public.payroll_approve(t,y,m,rev);END $$;
REVOKE ALL ON FUNCTION public.payroll_approve_work_draft(uuid,integer,integer,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_approve_work_draft(uuid,integer,integer,jsonb) TO authenticated;